// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract RateLimitedOracle {
    address public owner;
    address public trustedRelayer;

    uint256 public constant RATE_LIMIT_WINDOW = 1 hours;
    uint256 public constant MAX_REQUESTS_PER_WINDOW = 10;
    uint256 public constant RETRY_DELAY = 5 minutes;
    uint256 public constant MAX_RETRIES = 3;

    struct RequestState {
        uint256 windowStart;
        uint256 requestCount;
        uint256 lastRetryTimestamp;
        uint256 retryCount;
        bool pending;
    }

    struct QueryTemplate {
        bytes32 templateId;
        string baseExpression;
        bool active;
        uint256 paramCount;
    }

    mapping(address => RequestState) public requestStates;
    mapping(bytes32 => QueryTemplate) public templates;
    mapping(bytes32 => string) public queryResults;
    mapping(bytes32 => address) private queryOwners;

    event QuerySubmitted(bytes32 indexed queryId, address indexed requester, bytes32 templateId);
    event QueryResolved(bytes32 indexed queryId);
    event RetryScheduled(bytes32 indexed queryId, uint256 retryCount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyRelayer() {
        require(msg.sender == trustedRelayer, "Not relayer");
        _;
    }

    modifier rateLimited() {
        RequestState storage state = requestStates[msg.sender];
        if (block.timestamp >= state.windowStart + RATE_LIMIT_WINDOW) {
            state.windowStart = block.timestamp;
            state.requestCount = 0;
        }
        require(state.requestCount < MAX_REQUESTS_PER_WINDOW, "Rate limit exceeded");
        state.requestCount++;
        _;
    }

    constructor(address _relayer) {
        owner = msg.sender;
        trustedRelayer = _relayer;
    }

    function registerTemplate(
        bytes32 _templateId,
        string calldata _baseExpression,
        uint256 _paramCount
    ) external onlyOwner {
        templates[_templateId] = QueryTemplate({
            templateId: _templateId,
            baseExpression: _baseExpression,
            active: true,
            paramCount: _paramCount
        });
    }

    function _validateParam(string calldata _param) internal pure returns (bool) {
        bytes memory b = bytes(_param);
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            // Only allow alphanumeric and underscore
            if (!(
                (c >= 0x30 && c <= 0x39) || // 0-9
                (c >= 0x41 && c <= 0x5A) || // A-Z
                (c >= 0x61 && c <= 0x7A) || // a-z
                c == 0x5F                    // _
            )) {
                return false;
            }
        }
        return b.length > 0 && b.length <= 32;
    }

    function buildExpression(
        bytes32 _templateId,
        string[] calldata _params
    ) internal view returns (bytes32) {
        QueryTemplate storage tmpl = templates[_templateId];
        require(tmpl.active, "Template inactive");
        require(_params.length == tmpl.paramCount, "Param count mismatch");

        for (uint256 i = 0; i < _params.length; i++) {
            require(_validateParam(_params[i]), "Invalid param character");
        }

        // Return deterministic hash - expression never emitted or stored as string
        return keccak256(abi.encodePacked(_templateId, _params));
    }

    function submitQuery(
        bytes32 _templateId,
        string[] calldata _params
    ) external rateLimited returns (bytes32) {
        bytes32 expressionHash = buildExpression(_templateId, _params);

        bytes32 queryId = keccak256(
            abi.encodePacked(msg.sender, block.timestamp, expressionHash)
        );

        requestStates[msg.sender].pending = true;
        queryOwners[queryId] = msg.sender;

        emit QuerySubmitted(queryId, msg.sender, _templateId);
        return queryId;
    }

    function resolveQuery(
        bytes32 _queryId,
        string calldata _result
    ) external onlyRelayer {
        require(queryOwners[_queryId] != address(0), "Unknown query");
        queryResults[_queryId] = _result;
        emit QueryResolved(_queryId);
    }

    function retryQuery(
        bytes32 _templateId,
        string[] calldata _params,
        bytes32 _originalQueryId
    ) external rateLimited returns (bytes32) {
        RequestState storage state = requestStates[msg.sender];
        require(state.pending, "No pending query");
        require(queryOwners[_originalQueryId] == msg.sender, "Not query owner");
        require(
            block.timestamp >= state.lastRetryTimestamp + RETRY_DELAY,
            "Retry too soon"
        );
        require(state.retryCount < MAX_RETRIES, "Max retries exceeded");

        bytes32 expressionHash = buildExpression(_templateId, _params);

        bytes32 newQueryId = keccak256(
            abi.encodePacked(msg.sender, block.timestamp, _originalQueryId, expressionHash)
        );

        state.lastRetryTimestamp = block.timestamp;
        state.retryCount++;
        queryOwners[newQueryId] = msg.sender;

        emit RetryScheduled(newQueryId, state.retryCount);
        emit QuerySubmitted(newQueryId, msg.sender, _templateId);
        return newQueryId;
    }

    function getQueryResult(bytes32 _queryId) external view returns (string memory) {
        require(queryOwners[_queryId] == msg.sender || msg.sender == owner, "Not authorized");
        return queryResults[_queryId];
    }

    function resetRetryState() external {
        RequestState storage state = requestStates[msg.sender];
        state.retryCount = 0;
        state.pending = false;
        state.lastRetryTimestamp = 0;
    }
}
